# /etc/nginx/nginx.conf
worker_processes auto;
worker_rlimit_nofile 65535;
events { worker_connections 8192; }

http {
    upstream app {
        zone app 64k;
        server 127.0.0.1:9000 max_fails=3 fail_timeout=10s;
        keepalive 32;
    }
    set_real_ip_from 10.0.0.0/8;
    real_ip_header proxy_protocol;

    server {
        listen 8080 proxy_protocol;
        server_name _;
        location / {
            proxy_pass http://app;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_connect_timeout 3s;
            proxy_read_timeout 30s;
        }
        location /nginx-health { access_log off; return 200 "ok\n"; }
    }
    include /etc/nginx/conf.d/*.conf;
}

include /etc/nginx/stream.d/*.conf;

# /etc/nginx/conf.d/tls.conf
server {
    listen 443 ssl;
    http2 on;
    server_name example.test;
    ssl_certificate     /etc/nginx/certs/tls.crt;
    ssl_certificate_key /etc/nginx/certs/tls.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:SSL:10m;
    location / { proxy_pass http://app; }
}

sudo tee /etc/nginx/stream.d/pg.conf <<'EOF'
stream {
    upstream pg { server 127.0.0.1:5432; }
    server {
        listen 15432;
        proxy_pass pg;
        proxy_connect_timeout 3s;
        proxy_timeout 1h;
    }
}
EOF
sudo mkdir -p /etc/systemd/system/nginx.service.d
printf '[Service]\nLimitNOFILE=65535\n' | sudo tee /etc/systemd/system/nginx.service.d/limits.conf
sudo nginx -t && sudo systemctl daemon-reload && sudo systemctl enable nginx && sudo systemctl restart nginx
sudo nginx -t && sudo systemctl reload nginx
